+/** Picks the language from an Accept-Language header (q-values, region tags), else `fallback`. */
+export function pickLanguage(header, fallback = config.defaultLanguage) {
+  const ranked = String(header ?? "")
+    .split(",")
+    .map((part, index) => {
+      const [tag, ...params] = part.trim().split(";");
+      const q = params.map((p) => p.trim()).find((p) => /^q=/i.test(p));
+      const weight = q === undefined ? 1 : Number(q.slice(2));
+      return { lang: tag.trim().toLowerCase().split("-")[0], weight, index };
+    })
+    .filter((x) => x.lang && x.weight > 0 && LANGUAGES.includes(x.lang))
+    .sort((a, b) => b.weight - a.weight || a.index - b.index);
+  return ranked.length ? ranked[0].lang : fallback;
+}
